bicepWiring.enableEntraAuth:
resource pgAdAdmin 'Microsoft.DBforPostgreSQL/flexibleServers/administrators@2023-06-01-preview' = {
  parent: postgresServer
  name: managedIdentity.properties.principalId
  properties: {
    principalType: 'ServicePrincipal'
    principalName: managedIdentity.name
    tenantId: subscription().tenantId
  }
}

bicepWiring.firewallRule:
resource firewallAllowAzure 'Microsoft.DBforPostgreSQL/flexibleServers/firewallRules@2023-06-01-preview' = {
  parent: postgresServer
  name: 'AllowAllAzureServicesAndResourcesWithinAzureIps'
  properties: {
    startIpAddress: '0.0.0.0'
    endIpAddress: '0.0.0.0'
  }
}

bicepWiring.serverParameter:
resource azureAdExtension 'Microsoft.DBforPostgreSQL/flexibleServers/configurations@2023-06-01-preview' = {
  parent: postgresServer
  name: 'azure.extensions'
  properties: { value: 'AZURE_AD', source: 'user-override' }
}

sdkInitPattern.typescript:
import { DefaultAzureCredential } from '@azure/identity';
import { Client } from 'pg';

const credential = new DefaultAzureCredential();
const token = await credential.getToken('https://ossrdbms-aad.database.windows.net/.default');

const client = new Client({
  host: process.env.AZURE_POSTGRESQL_HOST,
  database: process.env.AZURE_POSTGRESQL_DATABASE,
  user: process.env.AZURE_POSTGRESQL_USER,
  password: token.token,
  ssl: { rejectUnauthorized: true },
  port: 5432
});
await client.connect();
